UPDATE t_p79443517_creative_poetry_plat.poems SET text = REPLACE(REPLACE(REPLACE(text, 'правду, запечатленную крестом!', E'правду,\nЗапечатленную крестом!'), 'призыв Господний, смотри, душа, не отвергай.', E'призыв Господний,\nСмотри, душа, не отвергай.'), 'то зов Господний! Спасенье даром получай!', E'то зов Господний!\nСпасенье даром получай!') WHERE id = 29;